		strncpy(s1 + strlen(s1), s2, sizeof(s1) - strlen(s1));
	}
#endif

	s1[sizeof(s1)-1] = '\0';
#ifdef ISSERVER
	syslog(LOG_ERR, "%s", s1);
	syslog(LOG_ERR, "Exiting.");
#endif
	fprintf(stderr, "Error: %s\n", s1);
}

void nbd_err(const char *s) {
	err_nonfatal(s);
	fprintf(stderr, "Exiting.\n");
	exit(EXIT_FAILURE);
}

void nbd_err_code(const char *s, int code) {
	err_nonfatal(s);
	fprintf(stderr, "Exiting.\n");
	exit(abs(code));
}

