Trim loop inside exptrim (nbdsrv.c):

```c
	if(client->server->flags & F_TREEFILES) {
		/* Remove the files for all blocks that are fully covered by
		 * the trim range. Partially covered blocks are left alone;
		 * the NBD protocol does not define what a client may expect
		 * to read from trimmed blocks. */
		off_t start = req->from;
		off_t end = req->from + req->len;
		off_t firstblk = (start + TREEPAGESIZE - 1) / TREEPAGESIZE;
		off_t lastblk = end / TREEPAGESIZE;
		for(off_t blk = firstblk; blk < lastblk; blk++) {
			delete_treefile(client->exportname, client->exportsize, blk * TREEPAGESIZE);
		}
		DEBUG("Performed TRIM request on treefiles from %llu to %llu", ...);
		return 0;
	}
```

