/*
 * Tree files support: an export backed by a tree of block files rather
 * than a single large file. The exportname is the root of the tree; each
 * file in the tree holds one TREEPAGESIZE-byte block of the export, and
 * no directory holds more than TREEDIRSIZE entries, adding a level of
 * TREE%-directories whenever that limit would be exceeded.
 */

#include "lfs.h"

#include <errno.h>
#include <fcntl.h>
#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>

#include <glib.h>

#include <cliserv.h>
#include <nbd-debug.h>
#include <nbdsrv.h>
#include "treefiles.h"

/**
 * Tree structure helper functions
 */

/**
 * Construct the path of the treefile holding the data at a given offset.
 *
 * The path is appended to the string already present in the name buffer,
 * which must be the (root of the) export's file tree. Recurses one level
 * per directory level of the tree, so the required nesting is determined
 * by the size of the export.
 *
 * @param name buffer holding the export name on entry; receives the
 * 	export name plus the path of the treefile on exit
 * @param lenmax the size of the name buffer
 * @param size total size of the export
 * @param pos offset into the export for which to construct the path
 * @param ppos [out] offset divided by the size of one subtree, to allow
 * 	the caller's caller to pick the next path component
 **/
void construct_path(char* name, int lenmax, off_t size, off_t pos, off_t* ppos) {
	if (lenmax<10)
		err("Char buffer overflow. This is likely a bug.");

	if (size<TREEDIRSIZE*TREEPAGESIZE) {
		// we are done, add filename
		snprintf(name,lenmax,"/FILE%04" PRIX64,(uint64_t)(pos/TREEPAGESIZE) % TREEDIRSIZE);
		*ppos = pos / (TREEPAGESIZE*TREEDIRSIZE);
	} else {
		construct_path(name+9,lenmax-9,size/TREEDIRSIZE,pos,ppos);
		char buffer[10];
		snprintf(buffer,sizeof(buffer),"/TREE%04" PRIX64,(uint64_t)(*ppos % TREEDIRSIZE));
		memcpy(name,buffer,9); // copy into string without trailing zero
		*ppos/=TREEDIRSIZE;
	}
}

/**
 * Delete the treefile holding the data at a given offset.
 *
 * @param name the (root of the) export's file tree
 * @param size total size of the export
 * @param pos offset into the export whose treefile should be deleted
 **/
void delete_treefile(char* name, off_t size, off_t pos) {
	char filename[256+strlen(name)];
	strcpy(filename,name);
	off_t ppos;
	construct_path(filename+strlen(name),256,size,pos,&ppos);

	DEBUG("Deleting treefile: %s",filename);

	if (unlink(filename)==-1)
		DEBUG("Deleting failed : %s",strerror(errno));
}

/**
 * Create all directories in a path, ignoring those that exist already.
 * The last component of the path is expected to be a file and is not
 * created.
 *
 * @param path the path whose directories should be created
 **/
void mkdir_path(char * path) {
	char *subpath=path+1;
	while ((subpath=strchr(subpath,'/'))) {
		*subpath='\0'; // path is modified in place with terminating null char instead of slash
		if (mkdir(path,0700)==-1) {
			if (errno!=EEXIST)
				err("Path access error! %m");
		}
		*subpath='/';
		subpath++;
	}
}

/**
 * Open the treefile holding the data at a given offset, creating it (and
 * any missing directories) if it does not exist yet. For a read-only
 * export, missing treefiles read as all zeroes, which is implemented by
 * handing out an anonymous temporary file.
 *
 * @param name the (root of the) export's file tree
 * @param mode the mode with which the treefile should be opened
 * @param size total size of the export
 * @param pos offset into the export whose treefile should be opened
 * @param mutex a mutex serializing treefile creation
 * @return a file descriptor for the treefile
 **/
int open_treefile(char* name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char filename[256+strlen(name)];
	strcpy(filename,name);
	off_t ppos;
	construct_path(filename+strlen(name),256,size,pos,&ppos);

	DEBUG("Accessing treefile %s ( offset %llu of %llu)",filename,(unsigned long long)pos,(unsigned long long)size);

	pthread_mutex_lock(mutex);
	int handle=open(filename, mode, 0600);
	if (handle<0 && errno==ENOENT) {
		if (mode & O_RDWR) {

			DEBUG("Creating new treepath");

			mkdir_path(filename);
			handle=open(filename, O_RDWR|O_CREAT, 0600);
			if (handle<0) {
				err("Error opening tree block file %m");
			}
		} else {

			DEBUG("Creating a dummy tempfile for reading");
			gchar * tmpname;
			/* The file is unlinked immediately, so any directory
			 * we may create files in will do; try a few. */
			tmpname = g_strdup_printf("%s/dummy-XXXXXX", name);
			handle = mkstemp(tmpname);
			if (handle<0) {
				g_free(tmpname);
				tmpname = g_strdup_printf("dummy-XXXXXX");
				handle = mkstemp(tmpname);
			}
			if (handle<0) {
				g_free(tmpname);
				tmpname = g_strdup_printf("%s/dummy-XXXXXX", P_tmpdir);
				handle = mkstemp(tmpname);
			}
			if (handle>=0) {
				unlink(tmpname); /* File will stick around whilst FD open */
			} else {
				err("Error opening tree block file %m");
			}
			g_free(tmpname);
		}
		char n = '\0';
		if (lseek(handle,TREEPAGESIZE-1,SEEK_SET)<0 || write(handle,&n,1)<1) {
			err("Error setting tree block file size %m");
		}
	}
	pthread_mutex_unlock(mutex);
	return handle;
}

